# -*- coding: utf-8 -*-
"""MANAPRINT — TESLA · 5 boules (création 2KEA, le 100e jeu) · maquette CANVA de Maeva (27/11/2026,
« tesla_canva_12_A4 »). Reprise TELLE QUELLE : 12 cartes / feuille A4 PAYSAGE (3 x 4). Chaque carte :
cadre arrondi, « Carte N° », « Tél : 89 22 23 05 », le titre T E S L A, la VRAIE TESLA Model 3 de face
au centre (dessin de la maquette posé en pochoir : en couleur, MANAPRINT le repeint, les chiffres
restent noirs) et 5 boules à pointillés autour.
RÈGLE (inchangée) — 5 numéros : à gauche en haut 1-15 · à gauche en bas + au centre en bas = 2 triés
16-30 (le plus petit à gauche) · à droite en haut et en bas = 2 triés 46-60.
Crieur : 1-30 et 46-60. Chiffres de la maquette (DejaVu Sans, 30 pt), noirs ; plage en petit en
haut de chaque boule.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""

import io, os, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

POLICE_NUM = "Helvetica"
for _nom, _f in (("DejaVuSansTS", "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"), ("VeraTS", None)):
    try:
        if _f is None:
            import reportlab
            _f = os.path.join(os.path.dirname(reportlab.__file__), "fonts", "Vera.ttf")
        pdfmetrics.registerFont(TTFont(_nom, _f)); POLICE_NUM = _nom
        break
    except Exception:
        continue
T_NUM = 30

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
# (centre x, ligne de base, plage) — dans l'ordre : g. haut, g. bas, centre bas, d. haut, d. bas
BOULES = [(31.181, 88.4126, (1, 15)), (31.181, 37.38898, (16, 30)), (140.315, 20.09764, (16, 30)),
          (249.449, 88.4126, (46, 60)), (249.449, 37.38898, (46, 60))]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        i = sorted(rng.sample(range(16, 31), 2)); g = sorted(rng.sample(range(46, 61), 2))
        t = (rng.randint(1, 15), i[0], i[1], g[0], g[1])
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c):
    if getattr(c, "_tesla_modele", False):
        return
    import base64
    av, ap = _DESSIN.split("@IMG@")
    av = av.replace("{H}", c._doc.getInternalFontName("Helvetica"))
    ap = ap.replace("{H}", c._doc.getInternalFontName("Helvetica"))
    c.beginForm("TESLA_CANVA", 0, 0, CELL_W, CELL_H)
    c._code.append("q\n" + av)
    _masque.poser(c, "TESLA_IMG", base64.b64decode(_PNG), 63.6378, 19.3319, 153.3543, 115.5409)
    c._code.append(ap + "\nQ")
    c.endForm()
    c._tesla_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("TESLA_CANVA")
    _txt(c, "Carte N° %05d" % (serie % 100000), 11.33858, 134.0787, "Helvetica", 6, colors.Color(.1, .1, .1))
    for (x, y, (a, b)), n in zip(BOULES, nums):
        _txt(c, str(n), x, y - 2.5, POLICE_NUM, T_NUM, col, centre=True)
        _txt(c, "%d-%d" % (a, b), x, y + 24, "Helvetica-Bold", 5.2, NOIR, centre=True)   # la plage (27/11)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("TESLA · 5 boules")
    rng = random.Random(int(serie_start) * 100003 + 100)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            _billet(c, ox, oy, serie, _numeros(rng), NOIR)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


